<template>
  <view class="arrival-page">
    <view class="heading"><text class="title">{{ warehouse ? '入库管理与到货验收' : '到货预报／入库申请' }}</text><button size="mini" :disabled="loading || busy || denied" @click="refresh">刷新</button></view>
    <text class="muted">{{ warehouse ? '按原申请分批验收 · 良品与破损分别入账' : canCreate ? '我的入库申请 · 提交后由货主管理员审核' : '本货主全部入库申请 · 审核与结果跟踪' }}</text>
    <text v-if="updated" class="muted">最近成功更新：{{ updated }}</text>
    <view v-if="error" class="error"><text>{{ error }}</text><button v-if="!denied" size="mini" @click="refresh">重新加载</button></view>
    <text v-if="loading && !data" class="muted">正在加载…</text>

    <template v-if="!recordId && !creating">
      <button v-if="canCreate && !warehouse" class="primary" @click="emit('create')">新增入库申请</button>
      <view class="filters"><input v-model="search" placeholder="申请单号、来源单号、供应商或商品" @confirm="filter"/><button size="mini" @click="filter">搜索</button></view>
      <picker :range="statuses" range-key="label" :value="statusIndex" @change="statusIndex=Number($event.detail.value);filter()"><view class="select">{{ statuses[statusIndex].label }} ▾</view></picker>
      <view class="dates"><label>业务日期起<input v-model="dateFrom" placeholder="YYYY-MM-DD"/></label><label>业务日期止<input v-model="dateTo" placeholder="YYYY-MM-DD"/></label><button size="mini" @click="filter">应用日期</button></view>
      <text v-if="data && !data.results?.length && !error" class="empty">当前条件下暂无入库申请</text>
      <view v-for="item in data?.results || []" :key="item.id" class="card clickable" @click="emit('open',item.id)">
        <view class="heading"><text class="name">{{ item.order_no }}</text><text class="badge">{{ item.status_label }}</text></view>
        <text>供应商：{{ item.supplier_name }}</text><text>仓库：{{ item.warehouse_name }}</text><text>预计到货：{{ time(item.eta) }}</text><text v-if="item.src_bill_no">来源单号：{{ item.src_bill_no }}</text><text v-if="item.reason" class="warning">{{ item.reason }}</text><text class="muted">查看申请与验收结果 ›</text>
      </view>
      <button v-if="data?.next" :disabled="loading || busy" @click="load(page+1)">加载更多</button>
    </template>

    <template v-if="creating || editing">
      <view class="card">
        <text class="section">{{ creating ? '新建到货预报' : '修改入库申请' }}</text>
        <picker :range="options.suppliers || []" range-key="name" :value="supplierIndex" @change="form.supplier_id=options.suppliers[Number($event.detail.value)].id"><view class="select">供应商：{{ supplierName || '请选择' }} ▾</view></picker>
        <picker :range="options.warehouses || []" range-key="name" :value="warehouseIndex" @change="form.warehouse_id=options.warehouses[Number($event.detail.value)].id"><view class="select">仓库：{{ warehouseName || '请选择授权仓库' }} ▾</view></picker>
        <label>业务日期<input v-model="form.biz_date" placeholder="YYYY-MM-DD"/></label>
        <label>预计到货时间（提交必填）<input v-model="form.eta" placeholder="YYYY-MM-DD HH:mm"/></label>
        <label>送货联系人（提交必填）<input v-model="form.delivery_contact" maxlength="80"/></label>
        <label>送货电话（提交必填）<input v-model="form.delivery_phone" maxlength="40"/></label>
        <label>来源单号<input v-model="form.src_bill_no" maxlength="60" placeholder="选填"/></label>
        <picker :range="deliveryMethods" range-key="label" :value="deliveryIndex" @change="form.delivery_method=deliveryMethods[Number($event.detail.value)].value"><view class="select">交货方式：{{ deliveryMethods[deliveryIndex].label }} ▾</view></picker>
        <label>车牌<input v-model="form.vehicle_no" maxlength="30" placeholder="选填"/></label>
        <label>送货备注<textarea v-model="form.delivery_note" maxlength="500" placeholder="选填"/></label>
      </view>
      <view v-for="(row,index) in form.lines" :key="row.key || row.id" class="card">
        <text class="name">{{ index+1 }}. {{ row.product_name }}</text><text class="muted">{{ row.product_code }} · 规格：{{ row.spec || '未记录' }} · 单位：{{ row.unit }}</text>
        <label>计划数量<input v-model="row.base_qty" type="digit"/></label><label>基本单位采购单价<input v-model="row.base_price" type="digit" placeholder="未记录可留空"/></label><label>行备注<input v-model="row.note" maxlength="200"/></label><button size="mini" :disabled="busy" @click="form.lines.splice(index,1)">移除此行</button>
      </view>
      <view class="card"><text class="section">选择本货主商品</text><view class="filters"><input v-model="productSearch" placeholder="名称、编码或 SKU（包含零库存商品）" @confirm="searchProducts"/><button size="mini" :disabled="loading || busy" @click="searchProducts">查找</button></view>
        <view v-for="p in options.results || []" :key="p.id" class="product-option"><text>{{ p.name }} · {{ p.code }} · 单位：{{ p.unit }}</text><button size="mini" :disabled="busy" @click="addProduct(p)">添加一行</button></view>
        <button v-if="options.next" size="mini" :disabled="loading || busy" @click="moreProducts">更多商品</button>
      </view>
      <view class="buttons"><button class="primary" :disabled="busy || loading || denied" @click="saveOrder">{{ busy ? '保存中…' : '保存草稿' }}</button><button v-if="editing" :disabled="busy" @click="editing=false">返回详情</button></view>
    </template>

    <template v-else-if="recordId && data">
      <view class="card"><text class="name">{{ data.order_no }}</text><text class="badge">{{ data.status_label }}</text><text>供应商：{{ data.supplier_name }}</text><text>仓库：{{ data.warehouse_name }}</text><text>预计到货：{{ time(data.eta) }}</text><text>送货：{{ data.delivery_contact || '未记录' }} · {{ data.delivery_phone || '未记录' }}</text><text v-if="data.src_bill_no">来源单号：{{ data.src_bill_no }}</text><text v-if="data.vehicle_no">车牌：{{ data.vehicle_no }}</text><text v-if="data.delivery_note">送货说明：{{ data.delivery_note }}</text><text v-if="data.reason" class="warning">处理原因：{{ data.reason }}</text><text v-if="data.no_stock_required" class="success">无需库存入账／无需上架</text><text v-if="data.legacy_notice" class="warning">{{ data.legacy_notice }}</text></view>
      <view class="buttons"><button v-for="a in data.allowed_actions" :key="a" :disabled="busy || loading || denied" @click="a==='edit'?startEdit():act(a)">{{ labels[a] }}</button></view>
      <text class="section">逐行到货结果</text>
      <view v-for="(row,index) in data.lines" :key="row.id" class="card"><text class="name">原单行 {{ index+1 }} · {{ row.product_name }}</text><text class="muted">{{ row.product_code }} · {{ row.spec || '规格未记录' }} · 单位：{{ row.unit }}</text>
        <view v-if="!data.legacy_notice" class="numbers"><text>计划 {{ formatQuantity(row.base_qty) }}</text><text>待审核验收 {{ formatQuantity(row.pending_qty) }}</text><text>已确认良品 {{ formatQuantity(row.qty_ok) }}</text><text>已确认破损 {{ formatQuantity(row.qty_damage) }}</text><text>已确认拒收 {{ formatQuantity(row.qty_reject) }}</text><text>待到货 {{ formatQuantity(row.waiting_qty) }}</text><text v-if="data.receiving_closed_at">最终短收 {{ formatQuantity(row.short_qty) }}</text><text>超收 {{ formatQuantity(row.over_qty) }}</text><text>已入账 {{ formatQuantity(row.posted_qty) }}</text><text>已上架 {{ formatQuantity(row.putaway_qty) }}</text></view><text v-else>计划 {{ formatQuantity(row.base_qty) }} · 验收数量待核对</text>
      </view>
      <text class="section">分批验收与上架</text><text class="muted">到货处理量＝良品＋破损＋拒收；接收入库量＝良品＋破损。破损不增加可用库存。</text>
      <view v-for="batch in data.batches" :key="batch.id" class="card">
        <text class="name">{{ batch.number }}</text><text class="badge">{{ stages[batch.stage] || batch.stage }}</text><text v-if="batch.posting_error" class="error">入账未完成，验收记录已保留，请仓管核对后重试。</text><text v-if="batch.stage==='NO_STOCK'" class="success">无需库存入账／无需上架</text><text v-if="batch.reason" class="warning">差异／处理原因：{{ batch.reason }}</text><text class="muted">提交 {{ time(batch.submitted_at) }} · 审核 {{ time(batch.approved_at) }}</text><text v-if="batch.posted_at" class="muted">入账 {{ time(batch.posted_at) }}</text>
        <view v-for="row in batch.lines" :key="row.id" class="batch-row"><text>{{ row.product_name }} · 单位：{{ row.unit }}</text><text>良品 {{ formatQuantity(row.qty_ok) }} · 破损 {{ formatQuantity(row.qty_damage) }} · 拒收 {{ formatQuantity(row.qty_reject) }}</text><text>库位 {{ row.location_name }} · 批次 {{ row.lot_no || '未记录' }}</text><text>生产 {{ row.mfg_date || '未记录' }} · 到期 {{ row.exp_date || '未记录' }}</text><text v-if="row.serial_no">序列号 {{ row.serial_no }}</text><text v-if="row.damage_reason">破损原因：{{ row.damage_reason }}</text><text v-if="row.reject_reason">拒收原因：{{ row.reject_reason }}</text><view class="buttons"><template v-for="p in row.photos" :key="p.id"><button size="mini" :disabled="busy" @click="preview(p)">查看照片 {{ p.id }}</button><button v-if="!p.sealed && batch.allowed_actions.includes('batch-edit')" size="mini" :disabled="busy" @click="removePhoto(batch,p)">删除照片</button></template><button v-if="warehouse && (batch.can_append_evidence || batch.allowed_actions.includes('batch-edit') || manager)" size="mini" :disabled="busy" @click="upload(batch,row)">追加照片（选填）</button></view></view>
        <text v-if="batch.allowed_actions.includes('batch-approve')" class="warning">本批待批准超收：{{ overage(batch) }}。超收必须填写差异原因，并明确批准。</text>
        <label v-if="batch.allowed_actions.includes('batch-approve')"><checkbox-group @change="approveOverage[batch.id]=$event.detail.value.includes('yes')"><label><checkbox value="yes" :checked="Boolean(approveOverage[batch.id])"/>我已核对并批准本批超收（如有）</label></checkbox-group></label>
        <view class="buttons"><button v-for="a in batch.allowed_actions" :key="a" :disabled="busy || loading || denied" @click="batchAction(batch,a)">{{ labels[a] }}</button></view>
        <template v-if="activeBatch===batch.id && batchEdit">
          <text class="hint">以下均为本次数量；同商品多个批次或库位请增加验收行。破损照片选填，破损、拒收原因必填。</text>
          <view v-for="(row,index) in receiptForm" :key="row.key" class="batch-row">
            <picker :range="lineChoices" range-key="label" :value="lineIndex(row)" @change="row.order_line_id=data.lines[Number($event.detail.value)].id"><view class="select">{{ lineChoices[lineIndex(row)]?.label }} ▾</view></picker>
            <picker :range="data.locations" range-key="code" :value="locationIndex(row.location_id)" @change="row.location_id=data.locations[Number($event.detail.value)].id"><view class="select">收货库位：{{ locationName(row.location_id) }} ▾</view></picker>
            <label>本次良品<input v-model="row.qty_ok" type="digit"/></label><label>本次破损<input v-model="row.qty_damage" type="digit"/></label><label>本次拒收<input v-model="row.qty_reject" type="digit"/></label>
            <label>批次<input v-model="row.lot_no"/></label><label>生产日期<input v-model="row.mfg_date" placeholder="YYYY-MM-DD"/></label><label>到期日期<input v-model="row.exp_date" placeholder="YYYY-MM-DD"/></label><label>序列号<input v-model="row.serial_no" placeholder="序列号商品逐件填写"/></label>
            <label>破损原因<textarea v-model="row.damage_reason" maxlength="500"/></label><label>拒收原因<textarea v-model="row.reject_reason" maxlength="500"/></label><button size="mini" :disabled="busy" @click="receiptForm.splice(index,1)">移除此行</button>
          </view>
          <label>本批差异原因（超收必填）<textarea v-model="batchReason" maxlength="500"/></label><view class="buttons"><button :disabled="busy" @click="addReceipt">增加批次／库位行</button><button class="primary" :disabled="busy || loading" @click="saveBatch(batch)">保存本批草稿</button><button :disabled="busy" @click="batchEdit=false">返回批次</button></view>
        </template>
        <view v-if="batch.putaway_task_id" class="batch-row"><text class="name">上架：{{ batch.putaway_status==='POSTED'?'已完成入账':'待作业／审核入账' }}</text><view v-for="row in batch.putaway_lines" :key="row.id" class="batch-row"><text>{{ row.product_name }} · {{ row.quality==='DAMAGED'?'残次':'良品' }} · 单位：{{ row.unit }}</text><text>应上架 {{ formatQuantity(row.qty_plan) }} · 已登记 {{ formatQuantity(row.qty_done) }}</text><text>{{ row.from_location }} → {{ row.to_location }}</text></view></view>
        <template v-if="activeBatch===batch.id && putawayEdit"><view v-for="row in putawayForm" :key="row.id" class="batch-row"><text>{{ row.product_name }} · {{ row.quality==='DAMAGED'?'残次':'良品' }} · 单位：{{ row.unit }}</text><text>已登记 {{ formatQuantity(row.qty_done) }}／{{ formatQuantity(row.qty_plan) }}</text><label>本次上架数量<input v-model="row.qty" type="digit"/></label><picker :range="putawayLocations(row)" range-key="code" :value="putawayLocationIndex(row)" @change="row.location_id=putawayLocations(row)[Number($event.detail.value)].id"><view class="select">目标库位：{{ locationName(row.location_id) }} ▾</view></picker></view><button class="primary" :disabled="busy || loading" @click="savePutaway(batch)">保存本次上架</button></template>
      </view>
      <text class="section">处理进度与记录</text><view class="card timeline"><view v-for="e in data.events" :key="e.id" class="event"><text class="name">{{ e.action }}</text><text class="muted">{{ time(e.time) }} · {{ e.actor }}</text><text v-if="e.reason">{{ e.reason }}</text><view v-for="(line,i) in e.lines" :key="i" class="muted"><text>{{ line.product_name || (line.order_line_id?'原单行 '+line.order_line_id:'上架行 '+line.id) }}：{{ line.qty != null ? formatQuantity(line.qty) : `良品 ${formatQuantity(line.qty_ok)} / 破损 ${formatQuantity(line.qty_damage)} / 拒收 ${formatQuantity(line.qty_reject)}` }}{{ line.unit?' · 单位：'+line.unit:'' }}</text><text v-if="line.location">库位 {{ line.location }} · 批次 {{ line.lot_no || '未记录' }} · 生产 {{ line.mfg_date || '未记录' }} · 到期 {{ line.exp_date || '未记录' }}</text><text v-if="line.serial_no">序列号 {{ line.serial_no }}</text><text v-if="line.damage_reason">破损原因：{{ line.damage_reason }}</text><text v-if="line.reject_reason">拒收原因：{{ line.reject_reason }}</text><button v-for="photoId in line.photo_ids || []" :key="photoId" size="mini" @click="preview({url:url(`batches/${e.receipt_id}/photos/${photoId}/`)})">查看当次照片 {{ photoId }}</button></view></view><text v-if="!data.events.length" class="muted">处理时间未记录</text></view>
      <view v-if="warehouse && data.batches.length" class="card"><label>追加处理说明<textarea v-model="note" maxlength="500"/></label><button :disabled="busy || !note.trim()" @click="writeBatch(data.batches[data.batches.length-1],'note',{reason:note})">保留说明记录</button></view>
    </template>
  </view>
</template>
<script setup>
import { formatQuantity } from '../quantity'
import {computed,onUnmounted,ref,watch} from 'vue'
const props=defineProps({transport:{type:Object,required:true},identity:String,visible:Boolean,recordId:[Number,String],creating:Boolean,warehouse:Boolean,manager:Boolean,canCreate:Boolean})
const emit=defineEmits(['open','create'])
const root='/api/inbound/orders/'
const data=ref(null),options=ref({}),loading=ref(false),busy=ref(false),error=ref(''),denied=ref(false),updated=ref('')
const search=ref(''),dateFrom=ref(''),dateTo=ref(''),statusIndex=ref(0),productSearch=ref(''),editing=ref(false),form=ref({lines:[]})
const receiptForm=ref([]),putawayForm=ref([]),batchEdit=ref(false),putawayEdit=ref(false),activeBatch=ref(0),batchReason=ref(''),approveOverage=ref({}),note=ref('')
let page=1,productPage=1,applied={},appliedProduct='',generation=0,alive=true,queued=false,writeKey=null,formVersion=null,batchVersion=null
const labels={edit:'修改申请',submit:'提交申请',withdraw:'撤回申请','owner-approve':'审核通过','owner-reject':'退回修改','warehouse-confirm':'确认并发布','warehouse-reject':'退回申请',close:'结束未到余量','batch-create':'登记后续到货',claim:'领取收货任务',start:'开始收货','batch-edit':'填写／修改本批验收','batch-submit':'提交本批验收','batch-approve':'审核通过并入账','batch-reject':'退回验收','retry-posting':'重试入账','putaway-claim':'领取上架','putaway-record':'登记本次上架','putaway-approve':'审核上架并入账','putaway-reject':'退回上架'}
const stages={DRAFT:'验收草稿',PENDING:'待仓库审核',REJECTED:'验收已退回',APPROVED:'验收通过，待入账',POSTED:'已入账',NO_STOCK:'处理完成',CANCELLED:'批次已取消'}
const statuses=computed(()=>[{value:'',label:'全部状态'},...Object.entries({DRAFT:'草稿',OWNER_PENDING:'待货主审核',OWNER_REJECTED:'货主退回',WHS_PENDING:'待仓库确认',WHS_REJECTED:'仓库退回',WHS_APPROVED:'等待到货／作业',...(props.warehouse?{RECEIPT_PENDING:'待审核验收',POSTING_FAILED:'过账失败',PUTAWAY_PENDING:'待确认上架'}:{}),CLOSED:'已完成'}).map(([value,label])=>({value,label}))])
const deliveryMethods=[{label:'未记录',value:''},{label:'到岸',value:'CIF'},{label:'派车',value:'DISPATCH'}]
const deliveryIndex=computed(()=>Math.max(0,deliveryMethods.findIndex(r=>r.value===form.value.delivery_method)))
const supplierIndex=computed(()=>Math.max(0,(options.value.suppliers || []).findIndex(r=>r.id===form.value.supplier_id)))
const warehouseIndex=computed(()=>Math.max(0,(options.value.warehouses || []).findIndex(r=>r.id===form.value.warehouse_id)))
const supplierName=computed(()=>(options.value.suppliers || []).find(r=>r.id===form.value.supplier_id)?.name)
const warehouseName=computed(()=>(options.value.warehouses || []).find(r=>r.id===form.value.warehouse_id)?.name)
const lineChoices=computed(()=>(data.value?.lines || []).map((r,i)=>({...r,label:`原单行 ${i+1} · ${r.product_name} · 单位：${r.unit}`})))
const lineIndex=row=>Math.max(0,data.value.lines.findIndex(r=>r.id===row.order_line_id))
const locationIndex=id=>Math.max(0,(data.value?.locations || []).findIndex(r=>r.id===id))
const locationName=id=>(data.value?.locations || []).find(r=>r.id===id)?.code || '请选择'
const time=v=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'时间未记录'
const active=()=>alive && props.visible && !denied.value && (typeof document==='undefined' || !document.hidden)
const url=suffix=>`${root}${props.recordId}/${suffix || ''}`
const uuid=()=>`arrival-${Date.now()}-${Math.random().toString(36).slice(2,12)}`
function failure(e,read=false){const status=Number(e?.statusCode || e?.status || e?.code);if([401,403].includes(status) || (status===404 && data.value && props.recordId)){data.value=null;options.value={};form.value={lines:[]};receiptForm.value=[];putawayForm.value=[];denied.value=true;error.value='入库访问权限已失效';return}if(status===409 && (editing.value || batchEdit.value || putawayEdit.value)){error.value='记录已变化，填写内容已保留。请先刷新，再重新打开编辑并核对最新记录后保存。';return}error.value=read?(data.value?'更新失败，当前为上次数据':'入库申请暂不可用，请重试'):(e?.message || e?.data?.detail || '操作失败，请重试')}
async function load(next=1){if(!active())return;if(loading.value || busy.value){queued=true;return}const tag=generation;loading.value=true;queued=false;error.value='';try{let result;if(props.creating){result=await props.transport.request({url:root+'arrival-options/',data:{page_size:20},silent:true});if(tag!==generation || !active())return;options.value=result;if(!form.value.biz_date)form.value={biz_date:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date()),eta:'',delivery_contact:'',delivery_phone:'',delivery_note:'',vehicle_no:'',src_bill_no:'',delivery_method:'',lines:[]}}else{result=await props.transport.request({url:props.recordId?url('progress/'):root,data:props.recordId?{}:{owner_portal:1,...applied,page:next,page_size:20},silent:true});if(tag!==generation || !active())return;if(props.recordId && !Array.isArray(result.lines))throw new Error('响应不完整');if(!props.recordId && !Array.isArray(result.results))throw new Error('响应不完整');if(next>1)result.results=Array.from(new Map([...(data.value?.results || []),...result.results].map(r=>[r.id,r])).values());data.value=result;page=next}updated.value=time(new Date().toISOString())}catch(e){if(tag===generation && active())failure(e,true)}finally{loading.value=false;if(queued && active())load(1)}}
function refresh(){generation++;load(1)}
function filter(){applied={search:search.value.trim(),state:statuses.value[statusIndex.value].value,date_from:dateFrom.value,date_to:dateTo.value};generation++;data.value=null;load(1)}
async function products(next=1){if(!active() || loading.value || busy.value)return;const tag=generation;loading.value=true;try{const r=await props.transport.request({url:root+'arrival-options/',data:{search:appliedProduct,page:next,page_size:20},silent:true});if(tag!==generation || !active())return;if(next>1)r.results=[...(options.value.results || []),...r.results];options.value=r;productPage=next}catch(e){if(tag===generation && active())failure(e,true)}finally{loading.value=false;if(queued && active())load(1)}}
function searchProducts(){if(loading.value || busy.value)return;appliedProduct=productSearch.value.trim();generation++;products(1)}
function moreProducts(){products(productPage+1)}
function addProduct(p){form.value.lines.push({key:uuid(),product_id:p.id,product_name:p.name,product_code:p.code,spec:p.spec,unit:p.unit,base_qty:'',base_price:Number(p.purchase_price)>0?p.purchase_price:'',note:''})}
function startEdit(){formVersion=data.value.version;form.value=JSON.parse(JSON.stringify(data.value));form.value.lines.forEach(row=>{row.base_qty=formatQuantity(row.base_qty);if(Number(row.base_price)===0)row.base_price=''});form.value.eta=data.value.eta?data.value.eta.slice(0,16).replace('T',' '):'';editing.value=true;products()}
async function write(path,body,method='POST',done=null){if(!active() || busy.value || loading.value)return;const tag=generation;const fingerprint=JSON.stringify([path,body,method]);if(writeKey?.fingerprint!==fingerprint)writeKey={fingerprint,id:uuid()};busy.value=true;error.value='';try{const r=await props.transport.request({url:path,method,data:{...body,request_id:writeKey.id},silent:true});if(tag!==generation || !active())return;writeKey=null;data.value=r;updated.value=time(new Date().toISOString());if(done)done(r)}catch(e){if(tag===generation && active())failure(e)}finally{busy.value=false;if(queued && active())load(1)}}
function saveOrder(){const f=form.value;if(!f.supplier_id || !f.warehouse_id || !f.lines.length){error.value='请选择供应商、授权仓库和商品';return}const eta=f.eta?f.eta.trim().replace(' ','T')+(f.eta.includes('+')?'':':00+08:00'):null;const body={receipt_mode:'BATCH',...(props.recordId?{version:formVersion}:{}),supplier_id:f.supplier_id,warehouse_id:f.warehouse_id,biz_date:f.biz_date,eta,delivery_contact:f.delivery_contact || '',delivery_phone:f.delivery_phone || '',vehicle_no:f.vehicle_no || '',delivery_note:f.delivery_note || '',src_bill_no:f.src_bill_no || '',delivery_method:f.delivery_method || '',lines:f.lines.map(r=>({...(r.id?{id:r.id}:{}),product_id:r.product_id,base_qty:r.base_qty,base_price:r.base_price || '0',note:r.note || ''}))};write(props.recordId?url(''):root,body,props.recordId?'PATCH':'POST',r=>{editing.value=false;if(!props.recordId)emit('open',r.id)})}
async function reasonFor(a){if(!['owner-reject','warehouse-reject','close','batch-reject','putaway-reject'].includes(a))return '';const r=await new Promise(resolve=>uni.showModal({title:labels[a],editable:true,placeholderText:'请填写原因（必填）',success:resolve,fail:()=>resolve({confirm:false})}));if(!r.confirm)return null;if(!r.content?.trim()){error.value='请填写原因';return null}return r.content.trim()}
async function act(a){const reason=await reasonFor(a);if(reason===null)return;write(url(`actions/${a}/`),{version:data.value.version,reason})}
function writeBatch(b,a,body={},done=null){return write(url(`batches/${b.id}/actions/${a}/`),{version:b.version,...body},'POST',done)}
async function batchAction(b,a){activeBatch.value=b.id;if(a==='batch-edit'){batchVersion=b.version;receiptForm.value=b.lines.map(r=>({...r,key:uuid(),qty_ok:formatQuantity(r.qty_ok),qty_damage:formatQuantity(r.qty_damage),qty_reject:formatQuantity(r.qty_reject)}));batchReason.value=b.reason;batchEdit.value=true;putawayEdit.value=false;if(!receiptForm.value.length)addReceipt();return}if(a==='putaway-record'){batchVersion=b.version;putawayForm.value=b.putaway_lines.filter(r=>Number(r.qty_done)<Number(r.qty_plan)).map(r=>({...r,qty:''}));putawayEdit.value=true;batchEdit.value=false;return}const reason=await reasonFor(a);if(reason===null)return;writeBatch(b,a,{reason,approve_overage:Boolean(approveOverage.value[b.id])},()=>{batchEdit.value=false;putawayEdit.value=false})}
function addReceipt(){receiptForm.value.push({key:uuid(),order_line_id:data.value.lines[0]?.id,location_id:null,qty_ok:'0',qty_damage:'0',qty_reject:'0',lot_no:'',mfg_date:'',exp_date:'',serial_no:'',damage_reason:'',reject_reason:''})}
function saveBatch(b){const lines=receiptForm.value.map(r=>({...(r.id?{id:r.id}:{}),order_line_id:r.order_line_id,location_id:r.location_id,qty_ok:r.qty_ok || '0',qty_damage:r.qty_damage || '0',qty_reject:r.qty_reject || '0',lot_no:r.lot_no || '',mfg_date:r.mfg_date || null,exp_date:r.exp_date || null,serial_no:r.serial_no || '',damage_reason:r.damage_reason || '',reject_reason:r.reject_reason || ''}));writeBatch({...b,version:batchVersion},'batch-edit',{reason:batchReason.value,lines},()=>{batchEdit.value=false})}
function putawayLocations(row){return (data.value?.locations || []).filter(location=>location.code!==row.from_location)}
function putawayLocationIndex(row){return Math.max(0,putawayLocations(row).findIndex(location=>location.id===row.location_id))}
function savePutaway(b){const rows=putawayForm.value.filter(r=>Number(r.qty)>0).map(r=>({id:r.id,location_id:r.location_id,qty:r.qty}));writeBatch({...b,version:batchVersion},'putaway-record',{putaway_lines:rows},()=>{putawayEdit.value=false})}
function overage(b){const own={};for(const row of b.lines)own[row.order_line_id]=(own[row.order_line_id] || 0)+Number(row.qty_ok)+Number(row.qty_damage)+Number(row.qty_reject);return data.value.lines.map((r,i)=>{const excess=Math.max(0,Number(r.qty_ok)+Number(r.qty_damage)+Number(r.qty_reject)+(own[r.id] || 0)-Number(r.base_qty));return excess?`原单行 ${i+1} ${r.product_name}：${Number(excess.toFixed(3))} ${r.unit}`:''}).filter(Boolean).join('；') || '无'}
async function upload(b,row){if(!active() || busy.value || loading.value)return;const tag=generation;busy.value=true;try{const files=await new Promise((resolve,reject)=>uni.chooseImage({count:1,sizeType:['compressed'],success:resolve,fail:reject}));if(tag!==generation || !active())return;const key=`upload:${b.id}:${row.id}:${files.tempFilePaths[0]}`;if(writeKey?.fingerprint!==key)writeKey={fingerprint:key,id:uuid()};const r=await props.transport.upload({url:url(`batches/${b.id}/photos/`),filePath:files.tempFilePaths[0],formData:{request_id:writeKey.id,version:b.version,line_id:row.id}});if(tag===generation && active()){data.value=r;writeKey=null}}catch(e){if(tag===generation && active())failure(e)}finally{busy.value=false;if(queued && active())load(1)}}
function removePhoto(b,p){write(p.url,{version:b.version},'DELETE')}
async function preview(p){const tag=generation;try{const image=await props.transport.image(p.url);if(tag===generation && active())uni.previewImage({urls:[image.url || image],complete:()=>image.revoke?.()});else image.revoke?.()}catch(e){if(tag===generation && active())failure(e)}}
watch(()=>[props.identity,props.recordId,props.creating],()=>{generation++;data.value=null;options.value={};form.value={lines:[]};receiptForm.value=[];putawayForm.value=[];editing.value=false;batchEdit.value=false;putawayEdit.value=false;denied.value=false;writeKey=null;error.value='';updated.value='';load(1)},{immediate:true})
watch(()=>props.visible,v=>{generation++;if(v)load(1)})
function visibility(){generation++;if(active())load(1)}
if(typeof document!=='undefined')document.addEventListener('visibilitychange',visibility)
onUnmounted(()=>{alive=false;generation++;if(typeof document!=='undefined')document.removeEventListener('visibilitychange',visibility)})
</script>
<style scoped>
.arrival-page{max-width:900px;margin:0 auto;padding:18px 16px 40px;background:#f5f7fb;min-height:100vh;color:#1f2937;box-sizing:border-box;font-size:15px}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.title{font-size:22px;font-weight:700;flex:1}.name{font-weight:650;font-size:17px;overflow-wrap:anywhere}.section{display:block;font-size:18px;font-weight:650;margin:22px 0 12px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px;margin-top:16px;overflow-wrap:anywhere}.card>text,.batch-row>text,.event>text{display:block;margin-bottom:7px}.muted>text{display:block}.muted{display:block;color:#64748b;line-height:1.7;font-size:13px}.badge{display:inline-block!important;background:#eaf2ff;color:#2456a9;border-radius:5px;padding:5px 8px;font-size:13px}.filters,.dates,.buttons{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:12px 0}.filters input{flex:1;min-width:160px}.buttons button{margin:0;font-size:14px}.dates label{flex:1;min-width:135px}.select{border:1px solid #cbd5e1;border-radius:7px;padding:12px;margin:10px 0;background:#fff}label{display:block;margin:12px 0;color:#334155;font-size:14px}input,textarea{display:block;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:7px;background:#fff;margin-top:6px;width:100%;padding:10px;min-height:40px;font-size:15px}textarea{height:86px}button{font-size:14px;line-height:2.7;border-radius:7px}button.primary{background:#2563eb;color:#fff}.numbers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:14px;font-size:14px}.batch-row{border-top:1px solid #e2e8f0;padding-top:14px;margin-top:14px;line-height:1.7}.warning{color:#a2530c;overflow-wrap:anywhere}.error{background:#fff1f2;color:#a62338;padding:12px;border-radius:8px;margin:12px 0;overflow-wrap:anywhere}.success{color:#187050}.hint{display:block;background:#f0f6ff;padding:12px;font-size:13px;line-height:1.7}.empty{display:block;padding:30px 0;text-align:center;color:#64748b}.product-option{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid #edf2f7}.product-option text{flex:1;overflow-wrap:anywhere}.product-option button{flex-shrink:0}.timeline .event{border-left:2px solid #bfd3ef;margin-left:4px;padding:0 0 22px 18px}.clickable{cursor:pointer}@media(max-width:480px){.card{padding:14px}.title{font-size:20px}.numbers{gap:10px;font-size:13px}.buttons button{max-width:100%;white-space:normal}.arrival-page{padding:14px 12px 32px}}
</style>
